puml.themes/shared_style:
' No <style> alternative found yet for skinparam maxMessageSize
skinparam maxMessageSize 150

' No <style> alternative found yet for skinparam StereotypeAlignment to make it work on elements that have nested elements
skinparam StereotypeAlignment right

'No <style> alternative found yet for skinparam lineType
!global $ARCH_LINETYPE ?= curve
skinparam lineType $ARCH_LINETYPE

' fallback values if theme does not define it
!global $ARCH_DEFAULT_BACKGROUND ?= "#white"
!global $ARCH_DEFAULT_FONT ?= "Verdana"
!global $ARCH_DEFAULT_FONTSIZE ?= 12
!global $ARCH_HANDWRITTEN_BACKGROUND ?= "#eeebdc"
!global $ARCH_HANDWRITTEN_FONT ?= "Comic Sans MS"
!global $ARCH_HANDWRITTEN_FONTSIZE ?= 14
!global $ARCH_RELATIONSHIP_FONTSIZE ?= 10
!global $ARCH_TECHNOLOGY_TYPE_FONTSIZE ?= 10

!global $ARCH_STRATEGY_FILLCOLOR ?= "#STRATEGY"
!global $ARCH_BUSINESS_FILLCOLOR ?= "#BUSINESS"
!global $ARCH_APPLICATION_FILLCOLOR ?= "#APPLICATION"
!global $ARCH_TECHNOLOGY_FILLCOLOR ?= "#TECHNOLOGY"
!global $ARCH_PHYSICAL_FILLCOLOR ?= "#PHYSICAL"
!global $ARCH_MOTIVATION_FILLCOLOR ?= "#MOTIVATION"
!global $ARCH_IMPLEMENTATION_FILLCOLOR ?= "#IMPLEMENTATION"
!global $ARCH_OTHER_FILLCOLOR ?= "#efd1e4"
!global $ARCH_JUNCTIONOR_FILLCOLOR ?= "#WhiteSmoke"
!global $ARCH_JUNCTIONAND_FILLCOLOR ?= "#Black"
!global $ARCH_GROUP_FILLCOLOR ?= "#LightGrey"
!global $ARCH_FOLDER_LINECOLOR ?= "#444444"
!global $ARCH_RELATIONSHIP_LINECOLOR ?= "#Black"
!global $ARCH_RELATIONSHIP_FONTCOLOR ?= "#Black"

!global $ARCH_MAXIMUM_WIDTH ?= 600
!global $ARCH_MINIMUM_WIDTH ?= 120

!global $ARCH_DIAGONAL_CORNER ?= 12
!global $ARCH_ROUND_CORNER ?= 25
!global $ARCH_ROUND_CORNER_LARGE ?= 80
!global $ARCH_SHARP_CORNER ?= 1

' $ARCH_SPECIAL_SHAPES drives the usage of special shapes for some elements.
' Note that there are some custom shapes that do not support nesting (actor and usecase).
' This means that when using these elements as containers, one must add `$nest=%true()` to the call, so that the regular shape will be used.
!global $ARCH_SPECIAL_SHAPES ?= %false()

<style>
    archimate {
        RoundCorner $ARCH_SHARP_CORNER
    }
    arrow {
        LineColor $ARCH_RELATIONSHIP_LINECOLOR
        FontColor $ARCH_RELATIONSHIP_FONTCOLOR
        FontSize $ARCH_RELATIONSHIP_FONTSIZE
    }
    element {
        FontName $ARCH_DEFAULT_FONT
        FontSize $ARCH_DEFAULT_FONTSIZE
        MaximumWidth $ARCH_MAXIMUM_WIDTH
        MinimumWidth $ARCH_MINIMUM_WIDTH
        HorizontalAlignment center
        stereotype {
            HorizontalAlignment right
        }
    }
    folder {
        .group {
            BackgroundColor $ARCH_GROUP_FILLCOLOR
            Shadowing 2
            stereotype {
                FontSize 1
                FontColor transparent
            }

        }
        .grouping {
            LineColor $ARCH_FOLDER_LINECOLOR
            LineStyle 8-5
            Shadowing 2
            stereotype {
                FontSize 1
                FontColor transparent
            }
        }
    }
    rectangle {
        .boundary {
            LineColor $ARCH_FOLDER_LINECOLOR
            LineStyle 8-5
            Shadowing 0
            stereotype {
                FontSize 1
                FontColor transparent
            }
        }
        RoundCorner $ARCH_SHARP_CORNER
    }
    root {
        BackgroundColor $ARCH_DEFAULT_BACKGROUND
    }
    .application-event {
        RoundCorner $ARCH_ROUND_CORNER
    }
    .application-function {
        RoundCorner $ARCH_ROUND_CORNER
    }
    .application-interaction {
        RoundCorner $ARCH_ROUND_CORNER
    }
    .application-process {
        RoundCorner $ARCH_ROUND_CORNER
    }
    .application-service {
        RoundCorner $ARCH_ROUND_CORNER
    }
    .business-event {
        RoundCorner $ARCH_ROUND_CORNER
    }
    .business-function {
        RoundCorner $ARCH_ROUND_CORNER
    }
    .business-interaction {
        RoundCorner $ARCH_ROUND_CORNER
    }
    .business-process {
        RoundCorner $ARCH_ROUND_CORNER
    }
    .business-service {
        RoundCorner $ARCH_ROUND_CORNER
    }
    .implementation-event {
        RoundCorner $ARCH_ROUND_CORNER
    }
    .implementation-workpackage {
        RoundCorner $ARCH_ROUND_CORNER
    }
    .motivation-assessment {
        DiagonalCorner $ARCH_DIAGONAL_CORNER
    }
    .motivation-constraint {
        DiagonalCorner $ARCH_DIAGONAL_CORNER
    }
    .motivation-driver {
        DiagonalCorner $ARCH_DIAGONAL_CORNER
    }
    .motivation-goal {
        DiagonalCorner $ARCH_DIAGONAL_CORNER
    }
    .motivation-meaning {
        DiagonalCorner $ARCH_DIAGONAL_CORNER
    }
    .motivation-outcome {
        DiagonalCorner $ARCH_DIAGONAL_CORNER
    }
    .motivation-principle {
        DiagonalCorner $ARCH_DIAGONAL_CORNER
    }
    .motivation-requirement {
        DiagonalCorner $ARCH_DIAGONAL_CORNER
    }
    .motivation-stakeholder {
        DiagonalCorner $ARCH_DIAGONAL_CORNER
    }
    .motivation-value {
        DiagonalCorner $ARCH_DIAGONAL_CORNER
    }
    .service-special {
        RoundCorner $ARCH_ROUND_CORNER_LARGE
        stereotype {
            FontSize 1
            FontColor transparent
        }
    }
    .strategy-capability {
        RoundCorner $ARCH_ROUND_CORNER
    }
    .strategy-courseofaction {
        RoundCorner $ARCH_ROUND_CORNER
    }
    .strategy-valuestream {
        RoundCorner $ARCH_ROUND_CORNER
    }
    .technology-event {
        RoundCorner $ARCH_ROUND_CORNER
    }
    .technology-function {
        RoundCorner $ARCH_ROUND_CORNER
    }
    .technology-interaction {
        RoundCorner $ARCH_ROUND_CORNER
    }
    .technology-process {
        RoundCorner $ARCH_ROUND_CORNER
    }
    .technology-service {
        RoundCorner $ARCH_ROUND_CORNER
    }

</style>
